screenPanels.initJs:
function(container, apiUrl, tables) {
  const dealTable = tables[0]; // 商談テーブル
  const customerTable = tables[1]; // 顧客テーブル

  let allDeals = [];
  let filteredDeals = [];
  let charts = {};

  // ユーティリティ: 日付フォーマット
  function formatDate(dateStr) {
    if (!dateStr) return '-';
    const d = new Date(dateStr);
    return d.toLocaleDateString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit' });
  }

  // ユーティリティ: 金額フォーマット
  function formatCurrency(num) {
    if (!num) return '¥0';
    return '¥' + num.toLocaleString('ja-JP');
  }

  // ユーティリティ: 顧客名取得
  function getCustomerName(customerId) {
    const customer = customerTable.records.find(c => c.顧客ID === customerId);
    return customer ? customer.顧客名 : '-';
  }

  // KPI 計算
  function updateKPIs() {
    const count = filteredDeals.length;
    const totalRevenue = filteredDeals.reduce((sum, d) => sum + (d.商談金額 || 0), 0);
    const avgProbability = count > 0 
      ? Math.round(filteredDeals.reduce((sum, d) => sum + (d.確度 || 0), 0) / count)
      : 0;

    // 今月成約予定
    const now = new Date();
    const currentMonth = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
    const thisMonthRevenue = filteredDeals
      .filter(d => d.予想成約日 && d.予想成約日.slice(0, 7) === currentMonth)
      .reduce((sum, d) => sum + (d.商談金額 || 0), 0);

    container.querySelector('[data-testid="kpi-count"]').textContent = count;
    container.querySelector('[data-testid="kpi-revenue"]').textContent = formatCurrency(totalRevenue);
    container.querySelector('[data-testid="kpi-probability"]').textContent = avgProbability + '%';
    container.querySelector('[data-testid="kpi-this-month"]').textContent = formatCurrency(thisMonthRevenue);
  }

  // テーブル描画
  function renderTable() {
    const tbody = container.querySelector('#deals-tbody');
    tbody.innerHTML = filteredDeals.map(deal => `
      <tr data-id="${deal.商談ID}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='var(--bg-main)'" onmouseout="this.style.background='transparent'">
        <td style="padding: 8px; color: var(--text);">${deal.商談ID.slice(0, 8)}</td>
        <td style="padding: 8px; color: var(--text); font-weight: 500;">${deal.商談名}</td>
        <td style="padding: 8px; color: var(--text);">${getCustomerName(deal.顧客ID)}</td>
        <td style="padding: 8px; color: var(--text);">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: var(--primary); color: #fff; font-size: 12px;">${deal.ステージ}</span>
        </td>
        <td style="padding: 8px; color: var(--text); text-align: right;">${formatCurrency(deal.商談金額)}</td>
        <td style="padding: 8px; color: var(--text); text-align: center; font-weight: 500;">${deal.確度}%</td>
        <td style="padding: 8px; color: var(--text);">${formatDate(deal.予想成約日)}</td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${formatDate(deal.更新日時)}</td>
      </tr>
    `).join('');

    // 行クリックで詳細表示
    tbody.querySelectorAll('tr[data-id]').forEach(row => {
      row.addEventListener('click', () => {
        const dealId = row.dataset.id;
        const deal = allDeals.find(d => d.商談ID === dealId);
        if (deal) showDetail(deal);
      });
    });
  }

  // 詳細パネル表示
  function showDetail(deal) {
    const detailContent = container.querySelector('#detail-content');
    detailContent.innerHTML = `
      <div style="display: grid; gap: 12px;">
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">商談ID</div>
          <div style="color: var(--text);">${deal.商談ID}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">商談名</div>
          <div style="color: var(--text); font-weight: 500;">${deal.商談名}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">顧客名</div>
          <div style="color: var(--text);">${getCustomerName(deal.顧客ID)}</div>
        </div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
          <div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">ステージ</div>
            <div style="color: var(--text);">${deal.ステージ}</div>
          </div>
          <div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">確度</div>
            <div style="color: var(--text);">${deal.確度}%</div>
          </div>
        </div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
          <div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">商談金額</div>
            <div style="color: var(--text); font-weight: 500;">${formatCurrency(deal.商談金額)}</div>
          </div>
          <div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">予定完了日</div>
            <div style="color: var(--text);">${formatDate(deal.予想成約日)}</div>
          </div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">説明</div>
          <div style="color: var(--text); white-space: pre-wrap; word-break: break-word;">${deal.説明 || '-'}</div>
        </div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; font-size: 12px;">
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">作成日時</div>
            <div style="color: var(--text);">${formatDate(deal.作成日時)}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); margin-bottom: 2px;">更新日時</div>
            <div style="color: var(--text);">${formatDate(deal.更新日時)}</div>
          </div>
        </div>
      </div>
    `;
    container.querySelector('#detail-modal').style.display = 'flex';
  }

  // グラフ: ステージ別件数
  function renderStageChart() {
    const stages = {};
    filteredDeals.forEach(d => {
      stages[d.ステージ] = (stages[d.ステージ] || 0) + 1;
    });
    const labels = Object.keys(stages);
    const data = Object.values(stages);

    if (charts.stage) charts.stage.destroy();
    const ctx = container.querySelector('#chart-stage').getContext('2d');
    charts.stage = new window.Chart(ctx, {
      type: 'bar',
      data: {
        labels,
        datasets: [{
          label: '件数',
          data,
          backgroundColor: '#0070d2',
          borderRadius: 4,
          borderSkipped: false
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: {
          y: { beginAtZero: true, ticks: { stepSize: 1 } }
        }
      }
    });
  }

  // グラフ: 確度分布
  function renderProbabilityChart() {
    const bins = { '0-20': 0, '21-40': 0, '41-60': 0, '61-80': 0, '81-100': 0 };
    filteredDeals.forEach(d => {
      const p = d.確度 || 0;
      if (p <= 20) bins['0-20']++;
      else if (p <= 40) bins['21-40']++;
      else if (p <= 60) bins['41-60']++;
      else if (p <= 80) bins['61-80']++;
      else bins['81-100']++;
    });

    if (charts.probability) charts.probability.destroy();
    const ctx = container.querySelector('#chart-probability').getContext('2d');
    charts.probability = new window.Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: Object.keys(bins),
        datasets: [{
          data: Object.values(bins),
          backgroundColor: ['#ff6b6b', '#ffa94d', '#ffd93d', '#6bcf7f', '#4ecdc4']
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { position: 'bottom' } }
      }
    });
  }

  // グラフ: 月別金額推移
  function renderMonthlyChart() {
    const months = {};
    filteredDeals.forEach(d => {
      if (d.予想成約日) {
        const month = d.予想成約日.slice(0, 7);
        months[month] = (months[month] || 0) + (d.商談金額 || 0);
      }
    });
    const sortedMonths = Object.keys(months).sort();
    const labels = sortedMonths.map(m => m.slice(5) + '月');
    const data = sortedMonths.map(m => months[m]);

    if (charts.monthly) charts.monthly.destroy();
    const ctx = container.querySelector('#chart-monthly').getContext('2d');
    charts.monthly = new window.Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: '金額',
          data,
          borderColor: '#0070d2',
          backgroundColor: 'rgba(0, 112, 210, 0.1)',
          tension: 0.3,
          fill: true,
          pointRadius: 4,
          pointBackgroundColor: '#0070d2'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: { y: { beginAtZero: true } }
      }
    });
  }

  // フィルター適用
  function applyFilters() {
    const searchText = container.querySelector('[data-testid="search-customer"]').value.toLowerCase();
    const stageFilter = container.querySelector('[data-testid="filter-stage"]').value;

    filteredDeals = allDeals.filter(d => {
      const customerName = getCustomerName(d.顧客ID).toLowerCase();
      const matchSearch = !searchText || customerName.includes(searchText) || d.商談名.toLowerCase().includes(searchText);
      const matchStage = !stageFilter || d.ステージ === stageFilter;
      return matchSearch && matchStage;
    });

    updateKPIs();
    renderTable();
    renderStageChart();
    renderProbabilityChart();
    renderMonthlyChart();
  }

  // CSV エクスポート
  container.querySelector('[data-testid="export-csv-button"]').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ['商談ID', '商談名', '顧客名', 'ステージ', '金額', '確度', '予定完了日', '最終更新日時'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...rows.map(r => [
        r.商談ID,
        `"${r.商談名}"`,
        `"${getCustomerName(r.顧客ID)}"`,
        r.ステージ,
        r.商談金額,
        r.確度,
        formatDate(r.予想成約日),
        formatDate(r.更新日時)
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'deals_' + new Date().toISOString().slice(0, 10) + '.csv';
    link.click();
  });

  // イベントリスナー
  container.querySelector('[data-testid="search-button"]').addEventListener('click', applyFilters);
  container.querySelector('[data-testid="reset-button"]').addEventListener('click', () => {
    container.querySelector('[data-testid="search-customer"]').value = '';
    container.querySelector('[data-testid="filter-stage"]').value = '';
    applyFilters();
  });

  container.querySelector('#close-detail').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target.id === 'detail-modal') {
      container.querySelector('#detail-modal').style.display = 'none';
    }
  });

  // 初期化
  async function init() {
    allDeals = await window.aivicApi.list(0) || dealTable.records;
    filteredDeals = [...allDeals];
    applyFilters();
  }

  init();
}

function(container, apiUrl, tables) {
  const reportTableIndex = 0; // 帳票テーブル（仮定）
  const customerTableIndex = 1; // 顧客テーブル（仮定）

  let allReports = [];
  let allCustomers = [];
  let selectedReportId = null;
  let selectedCustomerIds = new Set();
  let editingReportId = null;

  // DOM 要素
  const reportsList = container.querySelector('#reports-list');
  const detailPanel = container.querySelector('#detail-panel');
  const addReportBtn = container.querySelector('[data-testid="add-report-button"]');
  const reportSearchInput = container.querySelector('[data-testid="report-search-input"]');

  const reportModal = container.querySelector('#report-modal-overlay');
  const modalTitle = container.querySelector('#modal-title');
  const reportNameInput = container.querySelector('[data-testid="report-name-input"]');
  const reportTypeSelect = container.querySelector('[data-testid="report-type-select"]');
  const reportDescriptionTextarea = container.querySelector('[data-testid="report-description-textarea"]');
  const modalSaveBtn = container.querySelector('[data-testid="save-report-button"]');
  const modalCloseBtn = container.querySelector('#modal-close-btn');
  const modalCancelBtn = container.querySelector('#modal-cancel-btn');

  const deleteConfirmModal = container.querySelector('#delete-confirm-modal');
  const deleteConfirmBtn = container.querySelector('#delete-confirm-btn');
  const deleteCancelBtn = container.querySelector('#delete-cancel-btn');
  let pendingDeleteId = null;

  const customerSelectModal = container.querySelector('#customer-select-modal');
  const customerSearchInput = container.querySelector('[data-testid="customer-search-input"]');
  const customerList = container.querySelector('#customer-list');
  const customerSaveBtn = container.querySelector('[data-testid="save-customers-button"]');
  const customerCancelBtn = container.querySelector('#customer-cancel-btn');
  const customerModalCloseBtn = container.querySelector('#customer-modal-close-btn');

  // 初期化
  async function init() {
    try {
      // 帳票一覧を取得
      allReports = await window.aivicApi.list(reportTableIndex) || [];
      // 顧客一覧を取得
      allCustomers = await window.aivicApi.list(customerTableIndex) || [];

      renderReportsList(allReports);
    } catch (err) {
      console.error('Failed to load data:', err);
    }
  }

  // 帳票一覧をレンダリング
  function renderReportsList(reports) {
    reportsList.innerHTML = '';
    reports.forEach(report => {
      const item = document.createElement('div');
      item.className = 'report-item';
      item.dataset.id = report.id;
      item.style.cssText = `
        padding: 10px 12px;
        border-bottom: 1px solid var(--border);
        cursor: pointer;
        background: ${selectedReportId === report.id ? 'var(--bg-main)' : 'var(--bg-card)'};
        transition: background 0.2s;
      `;
      item.innerHTML = `
        <div style="font-size: 13px; font-weight: 500; color: var(--text); margin-bottom: 2px;">${report.reportName || '（無名）'}</div>
        <div style="font-size: 11px; color: var(--text-muted);">${report.reportType || '—'}</div>
        <div style="font-size: 11px; color: ${report.isPublished ? 'var(--primary)' : 'var(--text-muted)'}; margin-top: 4px;">
          ${report.isPublished ? '🔓 公開中' : '🔒 非公開'}
        </div>
      `;
      item.addEventListener('click', () => selectReport(report));
      reportsList.appendChild(item);
    });
  }

  // 帳票を選択して詳細を表示
  function selectReport(report) {
    selectedReportId = report.id;
    selectedCustomerIds = new Set(report.targetCustomerIds || []);
    renderReportsList(allReports);
    renderDetailPanel(report);
  }

  // 詳細パネルをレンダリング
  function renderDetailPanel(report) {
    const publishedCustomers = allCustomers.filter(c => selectedCustomerIds.has(c.id));

    detailPanel.innerHTML = `
      <div style="background: var(--bg-card); border-radius: 6px; padding: 16px; border: 1px solid var(--border);">
        <h2 style="margin: 0 0 16px 0; font-size: 16px; font-weight: 600; color: var(--text);">${report.reportName}</h2>

        <div style="display: grid; gap: 12px; margin-bottom: 16px;">
          <div>
            <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px; font-weight: 500; text-transform: uppercase;">帳票タイプ</label>
            <div style="font-size: 13px; color: var(--text);">${report.reportType || '—'}</div>
          </div>

          <div>
            <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px; font-weight: 500; text-transform: uppercase;">説明</label>
            <div style="font-size: 13px; color: var(--text); white-space: pre-wrap; word-break: break-word;">${report.description || '（説明なし）'}</div>
          </div>

          <div>
            <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px; font-weight: 500; text-transform: uppercase;">作成者</label>
            <div style="font-size: 13px; color: var(--text);">${report.createdBy || '—'}</div>
          </div>

          <div>
            <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px; font-weight: 500; text-transform: uppercase;">最終更新</label>
            <div style="font-size: 13px; color: var(--text);">${report.updatedAt ? new Date(report.updatedAt).toLocaleString('ja-JP') : '—'}</div>
          </div>
        </div>

        <div style="border-top: 1px solid var(--border); padding-top: 12px; margin-bottom: 16px;">
          <div style="display: flex; align-items: center; gap: 8px; margin-bottom: 12px;">
            <input 
              type="checkbox" 
              id="publish-toggle"
              ${report.isPublished ? 'checked' : ''}
              style="cursor: pointer; accent-color: var(--primary);"
            />
            <label for="publish-toggle" style="font-size: 13px; color: var(--text); cursor: pointer; font-weight: 500;">
              ポータルで公開
            </label>
          </div>

          ${report.isPublished ? `
            <div style="background: var(--bg-main); padding: 8px; border-radius: 4px; margin-bottom: 12px;">
              <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 6px;">公開対象顧客: <strong>${publishedCustomers.length}</strong> 件</div>
              <div style="font-size: 12px; color: var(--text);">
                ${publishedCustomers.length > 0 
                  ? publishedCustomers.slice(0, 3).map(c => c.customerName).join('、') + (publishedCustomers.length > 3 ? `ほか ${publishedCustomers.length - 3} 件` : '')
                  : '（対象顧客なし）'
                }
              </div>
            </div>
          ` : ''}
        </div>

        <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px;">
          <button class="edit-report-btn action-btn secondary" data-id="${report.id}" style="padding: 8px 12px; font-size: 12px; border: 1px solid var(--border); background: transparent; color: var(--text); cursor: pointer;">
            編集
          </button>
          <button class="select-customers-btn action-btn secondary" data-id="${report.id}" style="padding: 8px 12px; font-size: 12px; border: 1px solid var(--border); background: transparent; color: var(--text); cursor: pointer;">
            対象顧客
          </button>
          <button class="delete-report-btn action-btn secondary" data-id="${report.id}" style="padding: 8px 12px; font-size: 12px; border: 1px solid var(--border); background: transparent; color: #d32f2f; cursor: pointer;">
            削除
          </button>
        </div>
      </div>
    `;

    // イベントリスナー
    const publishToggle = detailPanel.querySelector('#publish-toggle');
    publishToggle.addEventListener('change', async (e) => {
      const updated = await window.aivicApi.update(reportTableIndex, report.id, {
        isPublished: e.target.checked
      });
      if (updated) {
        const idx = allReports.findIndex(r => r.id === report.id);
        if (idx >= 0) allReports[idx].isPublished = e.target.checked;
        selectReport(allReports[idx]);
      }
    });

    detailPanel.querySelector('.edit-report-btn').addEventListener('click', () => openEditModal(report));
    detailPanel.querySelector('.select-customers-btn').addEventListener('click', () => openCustomerSelectModal(report));
    detailPanel.querySelector('.delete-report-btn').addEventListener('click', () => openDeleteConfirmModal(report));
  }

  // 帳票追加モーダルを開く
  function openAddModal() {
    editingReportId = null;
    modalTitle.textContent = '帳票を追加';
    reportNameInput.value = '';
    reportTypeSelect.value = '';
    reportDescriptionTextarea.value = '';
    reportModal.style.display = 'flex';
  }

  // 帳票編集モーダルを開く
  function openEditModal(report) {
    editingReportId = report.id;
    modalTitle.textContent = '帳票を編集';
    reportNameInput.value = report.reportName || '';
    reportTypeSelect.value = report.reportType || '';
    reportDescriptionTextarea.value = report.description || '';
    reportModal.style.display = 'flex';
  }

  // 帳票追加・編集を保存
  async function saveReport() {
    const reportName = reportNameInput.value.trim();
    const reportType = reportTypeSelect.value;
    const description = reportDescriptionTextarea.value.trim();

    if (!reportName || !reportType) {
      alert('帳票名と帳票タイプは必須です');
      return;
    }

    const data = {
      reportName,
      reportType,
      description
    };

    let result;
    if (editingReportId) {
      result = await window.aivicApi.update(reportTableIndex, editingReportId, data);
      if (result) {
        const idx = allReports.findIndex(r => r.id === editingReportId);
        if (idx >= 0) allReports[idx] = { ...allReports[idx], ...data };
      }
    } else {
      result = await window.aivicApi.save(reportTableIndex, data);
      if (result) allReports.push(result);
    }

    if (result) {
      reportModal.style.display = 'none';
      renderReportsList(allReports);
    }
  }

  // 削除確認モーダルを開く
  function openDeleteConfirmModal(report) {
    pendingDeleteId = report.id;
    container.querySelector('#delete-confirm-message').textContent = `「${report.reportName}」を削除しますか？この操作は取り消せません。`;
    deleteConfirmModal.style.display = 'flex';
  }

  // 帳票を削除
  async function deleteReport() {
    if (!pendingDeleteId) return;

    const result = await window.aivicApi.delete(reportTableIndex, pendingDeleteId);
    if (result) {
      allReports = allReports.filter(r => r.id !== pendingDeleteId);
      selectedReportId = null;
      deleteConfirmModal.style.display = 'none';
      renderReportsList(allReports);
      detailPanel.innerHTML = '<div style="text-align: center; color: var(--text-muted); padding: 32px 16px;">帳票を選択してください</div>';
    }
  }

  // 公開対象顧客選択モーダルを開く
  function openCustomerSelectModal(report) {
    selectedCustomerIds = new Set(report.targetCustomerIds || []);
    renderCustomerList(allCustomers);
    customerSelectModal.style.display = 'flex';
  }

  // 顧客リストをレンダリング
  function renderCustomerList(customers) {
    customerList.innerHTML = '';
    customers.forEach(customer => {
      const label = document.createElement('label');
      label.style.cssText = 'display: flex; align-items: center; gap: 8px; padding: 6px; cursor: pointer; border-radius: 4px; transition: background 0.2s;';
      label.innerHTML = `
        <input 
          type="checkbox" 
          value="${customer.id}"
          ${selectedCustomerIds.has(customer.id) ? 'checked' : ''}
          style="cursor: pointer; accent-color: var(--primary);"
        />
        <span style="font-size: 13px; color: var(--text);">${customer.customerName}</span>
      `;
      label.addEventListener('mouseenter', () => label.style.background = 'var(--bg-card)');
      label.addEventListener('mouseleave', () => label.style.background = 'transparent');
      label.querySelector('input').addEventListener('change', (e) => {
        if (e.target.checked) {
          selectedCustomerIds.add(customer.id);
        } else {
          selectedCustomerIds.delete(customer.id);
        }
      });
      customerList.appendChild(label);
    });
  }

  // 公開対象顧客を保存
  async function saveCustomerSelection() {
    const result = await window.aivicApi.update(reportTableIndex, selectedReportId, {
      targetCustomerIds: Array.from(selectedCustomerIds)
    });
    if (result) {
      const idx = allReports.findIndex(r => r.id === selectedReportId);
      if (idx >= 0) allReports[idx].targetCustomerIds = Array.from(selectedCustomerIds);
      customerSelectModal.style.display = 'none';
      selectReport(allReports[idx]);
    }
  }

  // 検索フィルタ
  function filterReports(query) {
    const filtered = allReports.filter(r => 
      r.reportName.toLowerCase().includes(query.toLowerCase())
    );
    renderReportsList(filtered);
  }

  // 顧客検索フィルタ
  function filterCustomers(query) {
    const filtered = allCustomers.filter(c =>
      c.customerName.toLowerCase().includes(query.toLowerCase())
    );
    renderCustomerList(filtered);
  }

  // イベントリスナー登録
  addReportBtn.addEventListener('click', openAddModal);
  reportSearchInput.addEventListener('input', (e) => filterReports(e.target.value));
  customerSearchInput.addEventListener('input', (e) => filterCustomers(e.target.value));

  modalSaveBtn.addEventListener('click', saveReport);
  modalCloseBtn.addEventListener('click', () => reportModal.style.display = 'none');
  modalCancelBtn.addEventListener('click', () => reportModal.style.display = 'none');

  deleteConfirmBtn.addEventListener('click', deleteReport);
  deleteCancelBtn.addEventListener('click', () => deleteConfirmModal.style.display = 'none');

  customerSaveBtn.addEventListener('click', saveCustomerSelection);
  customerCancelBtn.addEventListener('click', () => customerSelectModal.style.display = 'none');
  customerModalCloseBtn.addEventListener('click', () => customerSelectModal.style.display = 'none');

  // Esc キーでモーダルを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      reportModal.style.display = 'none';
      deleteConfirmModal.style.display = 'none';
      customerSelectModal.style.display = 'none';
    }
  });

  // overlay クリックで閉じる
  reportModal.addEventListener('click', (e) => {
    if (e.target === reportModal) reportModal.style.display = 'none';
  });
  deleteConfirmModal.addEventListener('click', (e) => {
    if (e.target === deleteConfirmModal) deleteConfirmModal.style.display = 'none';
  });
  customerSelectModal.addEventListener('click', (e) => {
    if (e.target === customerSelectModal) customerSelectModal.style.display = 'none';
  });

  // 初期化実行
  init();
}
